"""Independent checker: rebuilds the canonical LP and validates a response."""
import numpy as np
from scipy import sparse
from scipy.optimize import linprog


def build(req):
    """Rebuild canonical LP pieces from a (known valid) request dict."""
    M = len(req["edges"])
    caps = np.array([float(e["capacity"]) for e in req["edges"]], dtype=np.float64)
    tail = [e["tail"] for e in req["edges"]]
    head = [e["head"] for e in req["edges"]]
    K = len(req["commodities"])
    failed = set(req["failed_edges"])
    budget = float(req["budget"])
    flat = []       # (owner, edges, live, a, demand)
    shape = []
    for ci, c in enumerate(req["commodities"]):
        dem = float(c["demand"])
        shape.append(len(c["paths"]))
        for pi, path in enumerate(c["paths"]):
            a = dem * float(c["previous"][pi]) / 16.0
            live = not (set(path) & failed)
            flat.append((ci, list(path), live, a, dem))
    P = len(flat)
    N = 2 * P + 1
    R = M + 3 * P + 2
    rows, cols, vals = [], [], []
    for j, (own, edges, live, a, dem) in enumerate(flat):
        for e in edges:
            rows.append(e); cols.append(j); vals.append(1.0)
    for e in range(M):
        rows.append(e); cols.append(2 * P); vals.append(-caps[e])
    for j in range(P):
        r1 = M + 2 * j
        rows += [r1, r1, r1 + 1, r1 + 1]
        cols += [j, P + j, j, P + j]
        vals += [1.0, -1.0, -1.0, -1.0]
    for j, (own, edges, live, a, dem) in enumerate(flat):
        rows.append(M + 2 * P + j); cols.append(j); vals.append(1.0)
    for j in range(P):
        rows.append(M + 3 * P); cols.append(P + j); vals.append(1.0)
    rows.append(M + 3 * P + 1); cols.append(2 * P); vals.append(1.0)
    A = sparse.coo_matrix((vals, (rows, cols)), shape=(R, N)).tocsr()
    b = np.zeros(R)
    for j, (own, edges, live, a, dem) in enumerate(flat):
        b[M + 2 * j] = a
        b[M + 2 * j + 1] = -a
        b[M + 2 * P + j] = dem if live else 0.0
    b[M + 3 * P] = 2.0 * budget
    b[M + 3 * P + 1] = 1.0
    er, ec, ev = [], [], []
    for j, (own, edges, live, a, dem) in enumerate(flat):
        er.append(own); ec.append(j); ev.append(1.0)
    E = sparse.coo_matrix((ev, (er, ec)), shape=(K, N)).tocsr()
    d = np.array([float(c["demand"]) for c in req["commodities"]], dtype=np.float64)
    c = np.zeros(N); c[2 * P] = 1.0
    return dict(M=M, K=K, P=P, N=N, R=R, caps=caps, A=A, b=b, E=E, d=d, c=c,
                flat=flat, shape=shape, tail=tail, head=head, budget=budget)


def lp_status(lp, method="highs"):
    A_eq = lp["E"] if lp["K"] > 0 else None
    b_eq = lp["d"] if lp["K"] > 0 else None
    res = linprog(lp["c"], A_ub=lp["A"], b_ub=lp["b"], A_eq=A_eq, b_eq=b_eq,
                  bounds=(0, None), method=method)
    return res


def check(req, resp, verbose=True):
    errs = []
    def bad(msg):
        errs.append(msg)
    if set(resp.keys()) != {"epoch", "status"} and "status" in resp:
        pass
    if resp.get("status") == "invalid":
        bad("planner said invalid for a valid request")
        return errs
    lp = build(req)
    M, K, P, R = lp["M"], lp["K"], lp["P"], lp["R"]
    if set(resp.keys()) != {"epoch", "status", "flows", "loads", "mlu",
                            "migration", "dual"} and resp.get("status") == "optimal":
        bad("optimal response key set %s" % sorted(resp.keys()))
    if set(resp.keys()) != {"epoch", "status", "certificate"} and resp.get("status") == "infeasible":
        bad("infeasible response key set %s" % sorted(resp.keys()))
    if resp.get("epoch") != req["epoch"]:
        bad("epoch mismatch")
    res = lp_status(lp)
    if res.status == 0:
        opt = float(res.fun)
    elif res.status == 2:
        opt = None
    else:
        bad("independent LP status %d" % res.status)
        return errs
    # cross check with a second method
    res2 = lp_status(lp, method="highs-ipm")
    if res2.status == 0 and opt is not None and abs(float(res2.fun) - opt) > 1e-7:
        bad("independent methods disagree %r %r" % (opt, res2.fun))
    if (opt is None) != (resp.get("status") == "infeasible"):
        bad("status mismatch: mine %s (opt=%r) theirs %s" %
            ("feasible" if opt is not None else "infeasible", opt, resp.get("status")))
        return errs

    if resp["status"] == "optimal":
        flows = resp["flows"]
        if len(flows) != K:
            bad("flows outer length"); return errs
        for ci, c in enumerate(req["commodities"]):
            if len(flows[ci]) != len(c["paths"]):
                bad("flows inner length commodity %d" % ci); return errs
        x = np.array([float(v) for row in flows for v in row], dtype=np.float64)
        if x.size != P:
            bad("flat flows size"); return errs
        for j in range(P):
            if not np.isfinite(x[j]) or x[j] < -1e-7:
                bad("flow %d out of range %r" % (j, x[j]))
        a = np.array([f[3] for f in lp["flat"]])
        t = np.abs(x - a)
        mlu = float(resp["mlu"])
        v = np.concatenate([x, t, [mlu]])
        if np.min(v) < -1e-7:
            bad("negative primal var")
        if K > 0:
            eqv = lp["E"].dot(v) - lp["d"]
            if np.max(np.abs(eqv)) > 1e-5:
                bad("equality violation %g" % np.max(np.abs(eqv)))
        ub = lp["A"].dot(v) - lp["b"]
        if ub.size and float(np.max(ub)) > 1e-5:
            bad("inequality violation %g" % float(np.max(ub)))
        # reported loads
        loads = np.array([float(z) for z in resp["loads"]])
        if loads.size != M:
            bad("loads length"); return errs
        true_loads = np.zeros(M)
        for j, f in enumerate(lp["flat"]):
            for e in f[1]:
                true_loads[e] += x[j]
        if M and float(np.max(np.abs(loads - true_loads))) > 1e-5:
            bad("reported loads mismatch %g" % float(np.max(np.abs(loads - true_loads))))
        true_mlu = float(np.max(true_loads / lp["caps"])) if M else 0.0
        if abs(mlu - true_mlu) > 1e-5:
            bad("reported mlu %r vs actual %r" % (mlu, true_mlu))
        true_mig = 0.5 * float(np.sum(t))
        if abs(float(resp["migration"]) - true_mig) > 1e-5:
            bad("reported migration %r vs %r" % (resp["migration"], true_mig))
        if not np.isfinite(mlu) or abs(mlu) > 1e8:
            bad("mlu magnitude")
        if abs(mlu - opt) > 2e-5:
            bad("mlu %r not optimal %r" % (mlu, opt))
        dual = resp["dual"]
        if set(dual.keys()) != {"inequality", "equality"}:
            bad("dual keys"); return errs
        y = np.array([float(z) for z in dual["inequality"]])
        q = np.array([float(z) for z in dual["equality"]])
        if y.size != R:
            bad("dual inequality length %d != %d" % (y.size, R)); return errs
        if q.size != K:
            bad("dual equality length"); return errs
        if y.size and float(np.max(y)) > 1e-7:
            bad("y positive %g" % float(np.max(y)))
        lhs = lp["A"].T.dot(y)
        if K > 0:
            lhs = lhs + lp["E"].T.dot(q)
        lhs = lhs - lp["c"]
        if float(np.max(lhs)) > 1e-7:
            bad("dual column violation %g" % float(np.max(lhs)))
        L = float(lp["b"].dot(y)) + (float(lp["d"].dot(q)) if K > 0 else 0.0)
        if abs(mlu - L) > 2e-5:
            bad("dual bound %r vs mlu %r" % (L, mlu))
        if y.size and float(np.max(np.abs(y))) > 1e8:
            bad("y magnitude")
        if q.size and float(np.max(np.abs(q))) > 1e8:
            bad("q magnitude")
        if float(np.max(np.abs(loads))) > 1e8 or float(np.max(np.abs(x))) > 1e8:
            bad("flows/loads magnitude")
    else:
        cert = resp["certificate"]
        if set(cert.keys()) != {"inequality", "equality"}:
            bad("certificate keys"); return errs
        y = np.array([float(z) for z in cert["inequality"]])
        q = np.array([float(z) for z in cert["equality"]])
        if y.size != R:
            bad("certificate inequality length %d != %d" % (y.size, R)); return errs
        if q.size != K:
            bad("certificate equality length %d != %d" % (q.size, K)); return errs
        if y.size and float(np.max(y)) > 1e-7:
            bad("farkas y positive %g" % float(np.max(y)))
        lhs = lp["A"].T.dot(y)
        if K > 0:
            lhs = lhs + lp["E"].T.dot(q)
        if float(np.max(lhs)) > 1e-7:
            bad("farkas column violation %g" % float(np.max(lhs)))
        L = float(lp["b"].dot(y)) + (float(lp["d"].dot(q)) if K > 0 else 0.0)
        if abs(L - 1.0) > 1e-5:
            bad("farkas normalization %r" % L)
        if y.size and float(np.max(np.abs(y))) > 1e8:
            bad("farkas y magnitude")
        if q.size and float(np.max(np.abs(q))) > 1e8:
            bad("farkas q magnitude")
    if verbose and errs:
        print("ERRORS:", errs)
    return errs
